"""
Trains the compatibility risk model on the honest, leak-free dataset.
"""
import pandas as pd
from sklearn.ensemble import RandomForestClassifier
import joblib
import os

def train():
    print("Loading preprocessed honest data...")
    # Read the NEW files generated by the updated preprocessor
    X_train = pd.read_csv("data/processed/X_train_compat.csv")
    y_train = pd.read_csv("data/processed/y_train_compat.csv").squeeze()

    print(f"Training shape: {X_train.shape}")

    print("\nTraining Random Forest...")
    rf = RandomForestClassifier(
        n_estimators=100, 
        random_state=42, 
        class_weight="balanced",
        n_jobs=-1
    )
    
    # Fitting directly on the DataFrame preserves feature names!
    rf.fit(X_train, y_train)

    os.makedirs("models/compatibility", exist_ok=True)
    joblib.dump(rf, "models/compatibility/random_forest.joblib")
    print("Model saved: models/compatibility/random_forest.joblib")

if __name__ == "__main__":
    train()